INSERT INTO "migrations" VALUES(5,'2026_09_15_000001_align_reservations_with_exam',1);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "reservation_slots" ("id" integer primary key autoincrement not null, "reservation_id" integer not null, "machine_id" integer not null, "starts_at" datetime not null, foreign key("reservation_id") references "reservations"("id") on delete cascade, foreign key("machine_id") references "machines"("id") on delete restrict);
