CREATE TABLE "reservations" ("id" integer primary key autoincrement not null, "user_id" integer not null, "machine_id" integer not null, "starts_at" datetime not null, "ends_at" datetime not null, "status" varchar not null default 'pendiente', "created_at" datetime, "updated_at" datetime, "garment_count" integer, foreign key("user_id") references "users"("id") on delete restrict, foreign key("machine_id") references "machines"("id") on delete restrict);
